pdfHtml:
function pdfHtml(p, soort, b) {
  var vandaag = new Date();
  var verval = soort === 'voorschot' ? new Date(vandaag.getTime() + CFG.betaaltermijnDagen * 864e5) : CFG.saldoTegen;
  var teBetalen = soort === 'voorschot' ? b.voorschot : b.saldo;
  var nummer = p.ref + (soort === 'saldo' ? '-S' : '-V');
  var mededeling = p.ref + ' ' + p.voornaam + ' ' + p.achternaam;
  var SANS = 'font-family:Helvetica,Arial,sans-serif;', SERIF = 'font-family:Georgia,\'Times New Roman\',serif;';
  var lbl = 'style="' + SANS + 'font-size:8px;letter-spacing:2.5px;color:' + TAUPE + ';text-transform:uppercase"';
  var td = 'padding:11px 0;border-bottom:1px solid ' + LIJN + ';' + SANS + 'font-size:11px;color:' + INK + ';';
  function kv(k, v) { return '<div ' + lbl + '>' + k + '</div><div style="' + SANS + 'font-size:11px;color:' + INK + ';margin:3px 0 12px">' + v + '</div>'; }

  return '<!doctype html><html><head><meta charset="utf-8"></head><body style="margin:0;' + SANS + 'color:' + INK + '">' +
  '<img src="data:image/png;base64,' + HEADER_PNG + '" style="width:100%;display:block">' +

  // titel + kerngegevens
  '<table style="width:100%;margin-top:34px;border-collapse:collapse"><tr>' +
    '<td style="vertical-align:bottom">' +
      '<div style="' + SERIF + 'font-size:34px;color:' + BORDEAUX + ';line-height:1">Betalingsverzoek</div>' +
      '<div style="' + SANS + 'font-size:11px;color:' + MUTED + ';margin-top:8px">' + (soort === 'voorschot' ? 'Voorschot 50% bij inschrijving' : 'Saldo 50% voor de start') + '</div></td>' +
    '<td style="vertical-align:bottom;text-align:right;width:58%">' +
      '<table style="border-collapse:collapse;margin-left:auto"><tr>' +
        '<td style="padding-left:22px;text-align:right;white-space:nowrap"><div ' + lbl + '>Nummer</div><div style="' + SANS + 'font-size:11px;margin-top:3px">' + esc(nummer) + '</div></td>' +
        '<td style="padding-left:22px;text-align:right;white-space:nowrap"><div ' + lbl + '>Datum</div><div style="' + SANS + 'font-size:11px;margin-top:3px">' + dat(vandaag) + '</div></td>' +
        '<td style="padding-left:22px;text-align:right;white-space:nowrap"><div ' + lbl + '>Vervaldatum</div><div style="' + SANS + 'font-size:11px;margin-top:3px;color:' + BORDEAUX + '"><b>' + dat(verval) + '</b></div></td>' +
      '</tr></table></td></tr></table>' +

  // van / aan
  '<table style="width:100%;margin-top:30px;border-collapse:collapse;border-top:1px solid ' + LIJN + '"><tr>' +
    '<td style="vertical-align:top;width:50%;padding-top:16px"><div ' + lbl + '>Van</div><div style="' + SANS + 'font-size:11px;line-height:1.65;margin-top:6px"><b>' + esc(CFG.bedrijf) + '</b><br>' + esc(CFG.adres) + '<br>Ondernemingsnr. ' + esc(CFG.btw) + '<br>' + esc(CFG.loulouMail) + '</div></td>' +
    '<td style="vertical-align:top;padding-top:16px"><div ' + lbl + '>Aan</div><div style="' + SANS + 'font-size:11px;line-height:1.65;margin-top:6px"><b>' + esc(p.voornaam + ' ' + p.achternaam) + '</b><br>' + esc(p.woonplaats || '') + (p.factuur ? '<br>' + esc(p.factuur) : '') + '<br>' + esc(p.email) + '</div></td>' +
  '</tr></table>' +

  // lijnen
  '<table style="width:100%;border-collapse:collapse;margin-top:30px">' +
    '<tr><td style="padding:0 0 8px;border-bottom:1px solid ' + BORDEAUX + '"><span ' + lbl + '>Omschrijving</span></td><td style="padding:0 0 8px;border-bottom:1px solid ' + BORDEAUX + ';text-align:right"><span ' + lbl + '>Bedrag</span></td></tr>' +
    '<tr><td style="' + td + '"><span style="' + SERIF + 'font-size:14px">Reformer Teacher Training · ' + esc(CFG.editie) + '</span><br><span style="color:' + MUTED + ';font-size:10px;line-height:1.8">' + esc(CFG.data) + ' · drie opleidingsweekends · tarief ' + esc(String(p.tarief).toLowerCase()) + '</span></td><td style="' + td + 'text-align:right;vertical-align:top">' + eur(b.excl) + '</td></tr>' +
  '</table>' +
  '<table style="width:46%;margin-left:54%;border-collapse:collapse;margin-top:6px">' +
    '<tr><td style="' + td + 'color:' + MUTED + '">Subtotaal excl. btw</td><td style="' + td + 'text-align:right;color:' + MUTED + '">' + eur(b.excl) + '</td></tr>' +
    '<tr><td style="' + td + 'color:' + MUTED + '">Btw 21%</td><td style="' + td + 'text-align:right;color:' + MUTED + '">' + eur(b.btw) + '</td></tr>' +
    '<tr><td style="' + td + '"><b>Totaal incl. btw</b></td><td style="' + td + 'text-align:right"><b>' + eur(b.incl) + '</b></td></tr>' +
    (soort === 'saldo' ? '<tr><td style="' + td + 'color:' + MUTED + '">Reeds betaald (voorschot)</td><td style="' + td + 'text-align:right;color:' + MUTED + '">– ' + eur(b.voorschot) + '</td></tr>' : '') +
  '</table>' +

  // te betalen
  '<table style="width:100%;border-collapse:collapse;margin-top:26px;border:1px solid ' + LIJN + ';border-left:4px solid ' + BORDEAUX + '"><tr>' +
    '<td style="padding:18px 22px;vertical-align:middle"><div ' + lbl + '>Nu te betalen</div><div style="' + SANS + 'font-size:11px;color:' + MUTED + ';margin-top:5px">' + (soort === 'voorschot' ? '50% van het totaal, uiterlijk ' : 'Saldo, uiterlijk ') + dat(verval) + '</div></td>' +
    '<td style="padding:18px 22px;text-align:right;vertical-align:middle;' + SERIF + 'font-size:36px;color:' + BORDEAUX + '">' + eur(teBetalen) + '</td>' +
  '</tr></table>' +

  // betaalgegevens
  '<table style="width:100%;border-collapse:collapse;margin-top:24px"><tr>' +
    '<td style="vertical-align:top;width:50%">' + kv('Begunstigde', esc(CFG.bedrijf)) + kv('IBAN', '<b>' + esc(CFG.iban) + '</b>') + '</td>' +
    '<td style="vertical-align:top">' + kv('BIC', esc(CFG.bic)) + kv('Mededeling', '<b>' + esc(mededeling) + '</b>') + '</td>' +
  '</tr></table>' +

  // voorwaarden
  '<div style="' + SANS + 'font-size:9.5px;line-height:1.7;color:' + MUTED + ';margin-top:10px;padding-top:14px;border-top:1px solid ' + LIJN + '">' +
    (soort === 'voorschot'
      ? 'Van dit voorschot is ' + eur(CFG.voorschotNietTerug) + ' niet terugbetaalbaar. Je plaats is definitief zodra we je betaling ontvangen. Het saldo van ' + eur(b.saldo) + ' betaal je uiterlijk ' + dat(CFG.saldoTegen) + '. '
      : 'Met deze betaling is je opleiding volledig betaald. ') +
    'Annuleren kan tot 2 maanden voor de start, met terugbetaling min het voorschot van ' + eur(CFG.voorschotNietTerug) + '. Binnen 2 maanden voor de start is annuleren niet meer mogelijk.</div>' +

  '<div style="' + SANS + 'font-size:8.5px;letter-spacing:.5px;color:' + TAUPE + ';margin-top:34px;text-align:center;line-height:1.8">' +
    esc(CFG.bedrijf) + ' · ' + esc(CFG.adres) + ' · ' + esc(CFG.loulouMail) + ' · louloustudio.be<br>' +
    'Dit is een betalingsverzoek, geen factuur. Je factuur ontvang je na betaling.</div>' +
  '</body></html>';
}
